function parseBody(value) {
  if (value && typeof value === 'object') return value;
  if (typeof value === 'string' && value.trim()) {
    try { return JSON.parse(value); } catch (error) { return {}; }
  }
  return {};
}
const body = parseBody($json.body);
const idToken = String(body.idToken || '').trim();
if (!idToken) return [{ json: { authorized: 'no', success: false, error: 'Authentication token is missing.' } }];
try {
  const lookup = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://identitytoolkit.googleapis.com/v1/accounts:lookup?key=AIzaSyDXz0gL67r9BafTg8nL6VdHYdw1tfcxhto',
    headers: { 'Content-Type': 'application/json' },
    body: { idToken },
    json: true
  });
  const user = Array.isArray(lookup?.users) ? lookup.users[0] : null;
  const email = String(user?.email || '').trim().toLowerCase();
  if (!email || !email.endsWith('@mranti.my')) {
    return [{ json: { authorized: 'no', success: false, error: 'Only authenticated @mranti.my users may access the Staff Directory.' } }];
  }
  return [{ json: { authorized: 'yes', success: true, userEmail: email } }];
} catch (error) {
  return [{ json: { authorized: 'no', success: false, error: 'Your Staff Directory session could not be verified. Please sign in again.' } }];
}

const payload = $json || {};
const sourceUsers = Array.isArray(payload.users) ? payload.users : [];
function text(value) { return value === null || value === undefined ? '' : String(value).trim(); }
function firstOrganisation(user) { return Array.isArray(user.organizations) ? (user.organizations[0] || {}) : {}; }
function joined(values, field = 'value') {
  if (!Array.isArray(values)) return '';
  return values.map(item => typeof item === 'string' ? text(item) : text(item?.[field])).filter(Boolean).join(', ');
}
const users = sourceUsers
  .filter(user => user.includeInGlobalAddressList !== false && !user.suspended && !user.archived)
  .map(user => {
    const name = user.name || {};
    const organisation = firstOrganisation(user);
    const fullName = text(name.fullName) || text(name.displayName) || text(user.primaryEmail);
    return {
      id: text(user.id),
      fullName,
      givenName: text(name.givenName),
      familyName: text(name.familyName),
      primaryEmail: text(user.primaryEmail),
      jobTitle: text(organisation.title),
      department: text(organisation.department),
      organisationName: text(organisation.name),
      organisationUnit: text(user.orgUnitPath),
      location: text(organisation.location),
      phoneNumbers: joined(user.phones),
      aliases: joined(user.aliases, 'unused'),
      additionalEmails: joined(user.emails, 'address')
    };
  })
  .map(user => ({ ...user, aliases: Array.isArray(sourceUsers.find(raw => String(raw.id) === user.id)?.aliases) ? sourceUsers.find(raw => String(raw.id) === user.id).aliases.map(text).filter(Boolean).join(', ') : '' }))
  .sort((a,b) => a.fullName.localeCompare(b.fullName, 'en', { sensitivity: 'base' }));
const departments = [...new Set(users.map(user => user.department).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
const locations = [...new Set(users.map(user => user.location).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
return [{ json: { success: true, totalUsers: users.length, departments, locations, generatedAt: new Date().toISOString(), users } }];
